method max_element(l: seq<int>) returns (maxVal: int)
    requires |l| > 0
    ensures maxVal == max(l)
{
    var maxSoFar := l[0];
    var i := 1;

    while i < |l|
        invariant 0 <= i <= |l|
        invariant maxSoFar == max(l[0..i])
    {
        if l[i] > maxSoFar {
            maxSoFar := l[i];
        }
        i := i + 1;
    }

    return maxSoFar;
}
